import { isUndefined } from 'lodash-es';
import React from 'react';

import { DownloadDataButton } from './DownloadDataButton.js';
import { ExploreButton } from './ExploreButton.js';
import { PanButton } from './PanButton.js';
import { ZoomInOutButtons } from './ZoomInOutButtons.js';
import { ZoomResetButton } from './ZoomResetButton.js';
import { Divider } from '../../../../typography/Divider.js';
import { ChartToolbarRenderer } from '../../../core/components/toolbar/ChartToolbarRenderer.js';
import { getA11yToolbarConfig } from '../../../core/functions/zoom.js';
import { useOverlaysEvents } from '../../../core/hooks/useOverlaysEvents.js';
import { zIndicesTimeseriesAreas } from '../../constants.js';
import { useChartInteractions } from '../../hooks/useChartInteractions.js';
import { useChartToolbar } from '../../hooks/useChartToolbar.js';

const defaultToolbarPlacement = 'top-right';

type TimeseriesChartToolbarProps = {
  onMouseEnter: (event?: React.MouseEvent<HTMLDivElement, MouseEvent>) => void;
  onMouseLeave: (event?: React.MouseEvent<HTMLDivElement, MouseEvent>) => void;
};

export const TimeseriesChartToolbar = ({
  onMouseEnter,
  onMouseLeave,
}: TimeseriesChartToolbarProps) => {
  const { isInChartBounds } = useOverlaysEvents();
  const config = useChartToolbar();
  const { zoom, zoomX, pan } = useChartInteractions();
  const isDownloadEnabled = config?.downloadData?.enabled ?? false;

  const anyInteractionEnabled =
    zoom?.enabled || zoomX?.enabled || pan?.enabled || isDownloadEnabled;

  const handleToggleMenu = (open: boolean): void => {
    !open && onMouseLeave();
  };

  return !isUndefined(config) && anyInteractionEnabled ? (
    <ChartToolbarRenderer
      visible={isInChartBounds}
      collapsed={config.collapsed}
      draggable={config.draggable}
      placement={config.placement || defaultToolbarPlacement}
      onToggleMenu={handleToggleMenu}
      initialA11yState={getA11yToolbarConfig({
        zoomX,
        pan,
        zoom,
        download: config.downloadData,
      })}
      zIndex={zIndicesTimeseriesAreas.toolbar}
      onMouseEnter={onMouseEnter}
      onMouseLeave={onMouseLeave}
    >
      <ExploreButton />
      <PanButton />
      <Divider orientation="vertical" as="hr" />
      <ZoomInOutButtons />
      <ZoomResetButton />
      {isDownloadEnabled && (
        <>
          <Divider orientation="vertical" as="hr" />
          <DownloadDataButton />
        </>
      )}
    </ChartToolbarRenderer>
  ) : null;
};

TimeseriesChartToolbar['displayName'] = 'ToolbarChartToolbar';
